import assert from 'node:assert/strict';import{readFileSync,readdirSync,writeFileSync}from'node:fs';import{spawnSync}from'node:child_process';import{createHash}from'node:crypto';
const root=process.cwd(),dir='/tmp/lite-helper-scan',hash=(x:string|Uint8Array)=>createHash('sha256').update(x).digest('hex');
const current=JSON.parse(readFileSync(root+'/compiler/reports/current-t00-t11-inventory.json','utf8'));
const sources=current.rows.map((r:any)=>({id:r.kind+':'+r.id,text:r.source}));
for(const p of readdirSync(root+'/igniter/tests/compiler').filter(p=>p.endsWith('.json')).sort()){const j=JSON.parse(readFileSync(root+'/igniter/tests/compiler/'+p,'utf8'));sources.push({id:p,text:readFileSync(root+'/igniter/tests/compiler/'+j.source.file,'utf8')});}
for(const [i,text]of [
 'outputLine('+JSON.stringify('lite$inputAll( "lite$divideInt( \\ lt_checked_add( lite_concat(')+');',
 '/* lite$inputAll( lt_checked_add( */ outputLine(42);',
 'inputLine := fn(): Int { 7 } outputLine(inputLine());',
 'outputLine(textLength(inputLine()));',
 'var lt_checked_add := 1; var lite_divide_int := 2; outputLine((lt_checked_add + lite_divide_int) / lite_divide_int);',
 'values := [(name = "lite$listAt(", value = 42)]; outputLine(values[0]);',
].entries())sources.push({id:'helper-hygiene-'+i,text});
const rows:any[]=[];
for(const target of ['ts','c'])for(const input of sources){const results=[];for(const artifact of target==='ts'?['previous-seed.ts','stage3.ts']:['previous-c-emitter.ts','c-emitter.ts']){
 const r=spawnSync(process.execPath,[root+'/compiler/entry.ts',dir+'/'+artifact,''],{cwd:root,input:input.text,timeout:10000,maxBuffer:32*1024*1024});assert.equal(r.error,undefined,input.id);assert.equal(r.signal,null,input.id);results.push(r);
}assert.equal(results[0]!.status,results[1]!.status,target+':'+input.id);assert.deepEqual(results[0]!.stdout,results[1]!.stdout,target+':'+input.id);assert.deepEqual(results[0]!.stderr,results[1]!.stderr,target+':'+input.id);rows.push({target,id:input.id,inputSha256:hash(input.text),status:results[0]!.status,stdoutSha256:hash(results[0]!.stdout),stderrSha256:hash(results[0]!.stderr)});}
writeFileSync(dir+'/exact-comparison.json',JSON.stringify({method:'Previous/current generated compilers in fresh processes, anonymous names, exact status/stdout/stderr; all current inventory sources, all compiler corpus sources, six quote/shadow/nesting cases. C comparisons include explicit rejections.',sources:sources.length,targetComparisons:rows.length,mismatches:0,rows},null,2)+'\n');console.log({sources:sources.length,targetComparisons:rows.length,mismatches:0});
